        "pen" => pen,
        "highlighter" => highlighter,
        "laser" => laser,
        "eraser" => eraser,
        "select" => select,
        "lasso" => lasso,
        "shapes" => shapes,
        "capture" => capture,
        "undo" => undo,
        "redo" => redo,
        "settings" => settings,
