        "color" => color,
        "check" => check,
        "more" => more,
        "dismiss" => dismiss,
        "board" => board,
        "passthrough" => passthrough,
        "delete" => delete,
        "chevronDown" => chevronDown,
        "chevronRight" => chevronRight,
        "pin" => pin,
        "square" => square,
        "circle" => circle,
        "triangle" => triangle,
        "arrowRight" => arrowRight,
        "laserFlash" => laserFlash,
        "laserFlashlight" => laserFlashlight,
