        _ => throw new System.ArgumentOutOfRangeException(nameof(name), name, "图标表里没有这个名字"),
    };

    /// <summary>外部库的图标带自己的 viewBox（比如 Material 用的是 960 网格）；没有就按 24 网格处理。</summary>
    public static bool TryGetBox(string name, out string box)
    {
        box = name switch
        {
            "msStylusLaser" => msStylusLaserBox,
            "msStylusLaserFill" => msStylusLaserFillBox,
            "msPointScan" => msPointScanBox,
            "msFlashlightOn" => msFlashlightOnBox,
            "msStylus" => msStylusBox,
            _ => null,
        };
        return box != null;
    }
}
